const bound=(v,min,max,defaultValue)=>Number.isFinite(Number(v))?Math.min(max,Math.max(min,Number(v))):defaultValue;
export function visualClip(c={}){return {zoom:bound(c.zoom,.5,2.5,1),rotation:bound(c.rotation,-180,180,0),brightness:bound(c.brightness,.2,2,1),contrast:bound(c.contrast,.2,2,1),saturation:bound(c.saturation,0,2,1),flip:!!c.flip,textColor:/^#[a-f0-9]{6}$/i.test(c.textColor||'')?c.textColor:'#f8f6f7',accentColor:/^#[a-f0-9]{6}$/i.test(c.accentColor||'')?c.accentColor:'#f7bacc'}}
export function splitAt(clips,selectedId,time,newId){let at=0;const next=clips.map(c=>({...c}));for(let i=0;i<next.length;i++){const c=next[i],length=(c.end-c.start)/c.speed;if(c.id===selectedId){const offset=time-at;if(offset<=.1||offset>=length-.1)throw new Error('Поставьте курсор внутри выбранной сцены, не ближе 0.1 сек к краю.');const source=c.start+offset*c.speed;const right={...c,id:newId,start:source,transition:'cut'};c.end=source;next.splice(i+1,0,right);return next}at+=length}throw new Error('Выберите сцену для разделения.')}
export function validateTimeline(state,assets){const result=[];if(!state.clips?.length)result.push('Таймлайн пуст');const ids=new Set();for(const [i,c]of (state.clips||[]).entries()){const a=assets.find(x=>x.id===c.assetId);if(!a)result.push(`Сцена ${i+1}: исходник отсутствует`);if(ids.has(c.id))result.push(`Сцена ${i+1}: повтор ID`);ids.add(c.id);if(!Number.isFinite(c.start)||!Number.isFinite(c.end)||c.end<=c.start)result.push(`Сцена ${i+1}: некорректная обрезка`);if(![.5,1,1.5,2].includes(c.speed))result.push(`Сцена ${i+1}: некорректная скорость`);if(a?.type==='video'&&c.end>a.duration+.01)result.push(`Сцена ${i+1}: обрезка за пределами файла`)}const total=(state.clips||[]).reduce((s,c)=>s+(c.end-c.start)/c.speed,0);for(const c of state.cues||[])if(c.end>total+.01)result.push('Субтитр выходит за длительность проекта');if(total>180)result.push('Браузерный WebM-экспорт ограничен 180 секундами');return [...new Set(result)]}

export function updatePlaybackButton(button,playing,createIcon){const next=String(playing);if(button.dataset.playing===next)return;button.dataset.playing=next;button.replaceChildren(createIcon(playing));button.setAttribute('aria-label',playing?'Пауза':'Воспроизвести');button.setAttribute('aria-pressed',next)}
